// One export standard for the whole app.
// CSV: UTF-8 with a BOM (Excel shows Arabic and other non-ASCII names), CRLF line ends, every cell
//      quoted, formula injection neutralised, the same columns whether or not there are rows, and
//      raw values (numbers as numbers, ISO dates) rather than screen formatting.
// PDF: a formal A4 document on the company letterhead (src/lib/a4/tableReport.ts): report name and
//      period top right, office, period, filters and "Generated by … on …" on page 1, the table with
//      its header repeated on every page, an optional totals row, "<report> · Page x of y".
//      Print gives the same pages (printTablePdf).
import { currentDocumentCompany, currentReportOffice, currentReportUser, orgName, type DocumentOffice } from '../lib/branding';
import type { ReportPeriod, ReportRow } from '../lib/a4/tableReport';
import type { Invoice, Payment } from '../types/finance';
import type { PayslipModalData } from '../types/hr';
import { todayYmd } from './date';

/**
 * Neutralise spreadsheet formula injection: a text cell that starts with = + - @ (or tab / CR)
 * is prefixed with an apostrophe so Excel/Sheets treat it as text. Real numbers and plain numeric
 * strings (e.g. "-12.500") are left untouched.
 */
export function csvSafeCell(val: unknown): string {
  const str = typeof val === 'object' ? JSON.stringify(val) : String(val);
  if (typeof val === 'number') return str;
  if (/^[-+]?\d+(\.\d+)?$/.test(str)) return str;
  return /^[=+\-@\t\r]/.test(str) ? `'${str}` : str;
}

const BOM = '﻿';
const quote = (v: unknown) => (v === null || v === undefined ? '""' : `"${csvSafeCell(v).replace(/"/g, '""')}"`);

/** CSV text (with BOM) from a header and rows of raw values. */
export function toCsv(header: string[], rows: unknown[][]): string {
  return BOM + [header, ...rows].map(r => r.map(quote).join(',')).join('\r\n') + '\r\n';
}

/** Save a Blob as a file. */
export function downloadBlob(fileName: string, blob: Blob): void {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

/** Download a CSV named `<filename>_<today>.csv` (pass `dated: false` for a fixed name, e.g. a template). */
export function downloadCsv(filename: string, header: string[], rows: unknown[][], opts: { dated?: boolean } = {}): void {
  const name = opts.dated === false ? `${filename}.csv` : `${filename}_${todayYmd()}.csv`;
  downloadBlob(name, new Blob([toCsv(header, rows)], { type: 'text/csv;charset=utf-8' }));
}

/**
 * CSV of objects. With `headers` the columns are exactly those, in that order (stable even when
 * there are no rows); without, the keys of the first row.
 */
export function exportToCSV<T extends Record<string, any>>(
  filename: string,
  data: T[],
  headers?: { key: keyof T; label: string }[],
): void {
  const cols = headers?.length ? headers : Object.keys(data[0] ?? {}).map(k => ({ key: k as keyof T, label: k }));
  downloadCsv(filename, cols.map(c => c.label), (data ?? []).map(item => cols.map(c => item[c.key])));
}

/** JSON download. */
export function exportToJSON(filename: string, data: any): void {
  downloadBlob(`${filename}_${todayYmd()}.json`, new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }));
}

/** One cell as plain text for PDF / preview output. */
export function cellToText(val: unknown): string {
  if (val === null || val === undefined) return '';
  if (typeof val === 'number') return Number.isInteger(val) ? String(val) : val.toFixed(3);
  if (typeof val === 'boolean') return val ? 'Yes' : 'No';
  if (typeof val === 'object') return '';
  return String(val);
}

export interface PdfOptions {
  /** One extra line under the seller line. */
  subtitle?: string;
  /** The filters the data was produced with, e.g. [['Category', 'Fuel']]; empty values are left out. */
  filters?: [string, string][];
  /** Column indexes to right-align (figures). */
  rightAlign?: number[];
  /** A totals row printed once, after the last row. */
  totals?: string[];
  /** The office of the rows; defaults to the office chosen in the header (null = All offices). */
  office?: DocumentOffice | null;
  /** Dated reports: { from, to }; statements as of a date: { asOf }. Lists default to "As of today". */
  period?: ReportPeriod;
  /** Facts printed first on page 1 (a statement's party, for example). */
  facts?: [string, string][];
  /** Signature lines after the table, e.g. ['Prepared by', 'Approved by']. */
  signatures?: [string, string];
  /** A fixed file name instead of <name>_<office>_<period>.pdf. */
  fileName?: string;
  /** Text for the "Office" fact instead of the office name. */
  officeLabel?: string;
}

async function tablePdf(filename: string, title: string, columns: string[], rows: ReportRow[], opts: PdfOptions) {
  const m = await import('../lib/a4/tableReport');
  const assets = await m.loadReportAssets(m.needsLandscape(columns.length));
  const company = documentCompany();
  return m.buildTableReportPdf({
    name: filename, title, columns, rows,
    rightAlign: opts.rightAlign, totals: opts.totals, subtitle: opts.subtitle, filters: opts.filters,
    office: opts.office === undefined ? currentReportOffice() : opts.office,
    period: opts.period,
    facts: opts.facts, signatures: opts.signatures, fileName: opts.fileName, officeLabel: opts.officeLabel,
    company,
    generatedBy: currentReportUser(),
  }, assets);
}

/**
 * Download a table as a formal A4 PDF on the letterhead (no print dialog). jsPDF is loaded on
 * demand. An empty table still produces the document ("No rows"), so the file says what was asked.
 */
export async function exportToPDF(filename: string, title: string, columns: string[], rows: ReportRow[], opts: PdfOptions = {}): Promise<void> {
  const { doc, fileName } = await tablePdf(filename, title, columns, rows, opts);
  const { savePdf } = await import('../lib/a4/frame');
  savePdf(doc, fileName);
}

/** Print the same pages exportToPDF would download (downloads them when the browser cannot print a PDF). */
export async function printTablePdf(filename: string, title: string, columns: string[], rows: ReportRow[], opts: PdfOptions = {}): Promise<'printed' | 'downloaded'> {
  const { doc, fileName } = await tablePdf(filename, title, columns, rows, opts);
  const { printPdf } = await import('../lib/a4/frame');
  return printPdf(doc, fileName);
}

/** Download or print a table PDF: one entry point for pages with a Download PDF and a Print button. */
export function tablePdfAction(print: boolean, filename: string, title: string, columns: string[], rows: ReportRow[], opts: PdfOptions = {}): Promise<'printed' | 'downloaded' | 'saved'> {
  return print ? printTablePdf(filename, title, columns, rows, opts) : exportToPDF(filename, title, columns, rows, opts).then(() => 'saved' as const);
}

/** The organization from Settings, with its display name when the legal name is not set yet. */
const documentCompany = () => { const c = currentDocumentCompany(); return { ...c, legalName: c.legalName || orgName() }; };

/** Payment receipt (money in) or payment voucher (money out) on the letterhead: print or download. */
export async function voucherPdfAction(print: boolean, payment: Payment, o: { office: DocumentOffice | null; currency: string; bankAccountNumber?: string; invoice?: Invoice | null }): Promise<'printed' | 'downloaded' | 'saved'> {
  const [v, f] = await Promise.all([import('../lib/a4/vouchers'), import('../lib/a4/frame')]);
  const d = v.voucherData(payment, { ...o, company: documentCompany() });
  const doc = v.buildVoucherPdf(d, await f.loadLetterheadBytes());
  if (print) return f.printPdf(doc, d.fileName);
  f.savePdf(doc, d.fileName);
  return 'saved';
}

/** Payslip on the letterhead (bank account masked to its last 4 characters): print or download. */
export async function payslipPdfAction(print: boolean, payslip: PayslipModalData, o: { office: DocumentOffice | null; currency: string }): Promise<'printed' | 'downloaded' | 'saved'> {
  const [v, f] = await Promise.all([import('../lib/a4/vouchers'), import('../lib/a4/frame')]);
  const d = v.payslipData(payslip, { ...o, company: documentCompany() });
  const doc = v.buildPayslipPdf(d, [payslip.designation, payslip.department].filter(Boolean), await f.loadLetterheadBytes());
  if (print) return f.printPdf(doc, d.fileName);
  f.savePdf(doc, d.fileName);
  return 'saved';
}

/** An office as printed on documents (code, name and its own VAT/CR when it has them). */
export const documentOffice = (c?: Pick<DocumentOffice, 'code' | 'name' | 'vatNumber' | 'registrationNumber'> | null): DocumentOffice | null =>
  c ? { code: c.code, name: c.name, vatNumber: c.vatNumber, registrationNumber: c.registrationNumber } : null;
